-- Atomic rate limiting for public Edge flows that use service-role access.
-- Keys are SHA-256 digests generated by the Edge Function; no raw identity or
-- client address is stored in this table.

CREATE TABLE IF NOT EXISTS public.public_rate_limits (
  scope text NOT NULL,
  key_hash text NOT NULL,
  window_started_at timestamptz NOT NULL DEFAULT now(),
  attempts integer NOT NULL DEFAULT 1 CHECK (attempts > 0),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (scope, key_hash)
);

ALTER TABLE public.public_rate_limits ENABLE ROW LEVEL SECURITY;

-- No browser-facing policies are intentionally created. The service-role Edge
-- Function consumes the SECURITY DEFINER RPC below.

CREATE OR REPLACE FUNCTION public.consume_public_rate_limit(
  _scope text,
  _key_hash text,
  _max_attempts integer,
  _window_seconds integer
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _allowed boolean;
BEGIN
  IF _scope IS NULL OR btrim(_scope) = ''
     OR _key_hash IS NULL OR _key_hash !~ '^[a-f0-9]{64}$'
     OR _max_attempts < 1
     OR _window_seconds < 1 THEN
    RAISE EXCEPTION 'invalid_rate_limit_arguments';
  END IF;

  INSERT INTO public.public_rate_limits (
    scope,
    key_hash,
    window_started_at,
    attempts,
    updated_at
  )
  VALUES (
    _scope,
    _key_hash,
    now(),
    1,
    now()
  )
  ON CONFLICT (scope, key_hash)
  DO UPDATE SET
    attempts = CASE
      WHEN public.public_rate_limits.window_started_at
           <= now() - make_interval(secs => _window_seconds)
        THEN 1
      ELSE public.public_rate_limits.attempts + 1
    END,
    window_started_at = CASE
      WHEN public.public_rate_limits.window_started_at
           <= now() - make_interval(secs => _window_seconds)
        THEN now()
      ELSE public.public_rate_limits.window_started_at
    END,
    updated_at = now()
  RETURNING attempts <= _max_attempts
  INTO _allowed;

  RETURN COALESCE(_allowed, false);
END;
$$;

REVOKE ALL ON TABLE public.public_rate_limits
  FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.consume_public_rate_limit(
  text,
  text,
  integer,
  integer
) FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.consume_public_rate_limit(
  text,
  text,
  integer,
  integer
) TO service_role;

-- Opportunistic cleanup helper for operators/cron. It is not browser callable.
CREATE OR REPLACE FUNCTION public.cleanup_public_rate_limits(
  _older_than interval DEFAULT interval '2 days'
)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _deleted bigint;
BEGIN
  DELETE FROM public.public_rate_limits
  WHERE updated_at < now() - _older_than;
  GET DIAGNOSTICS _deleted = ROW_COUNT;
  RETURN _deleted;
END;
$$;

REVOKE ALL ON FUNCTION public.cleanup_public_rate_limits(interval)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.cleanup_public_rate_limits(interval)
  TO service_role;
